import json,csv,re,hashlib,statistics as st,math,random
T=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
S=list(csv.DictReader(open('data/scores.csv')))
print(len(T),len(S))
print(hashlib.sha256(open('data/scores.csv','rb').read()).hexdigest())
tm={t['rating_id']:t for t in T}
mism=[]
for s in S:
    t=tm.get(s['rating_id'])
    if t is None: print('missing',s);continue
    fs=re.findall(r'FINAL SCORE:\s*(\d+)',t['judge_output'])
    for k in ['response_id','session','displayed_label']:
        if str(t[k])!=s[k]: print('meta mismatch',k,s,t[k])
    if len(fs)!=1 or int(fs[-1])!=int(s['score']) : mism.append((s,fs,t['judge_output']))
    if f"Displayed author: {s['displayed_label']}" not in t['judge_output']: print('label text mismatch', s['rating_id'])
    if t['judge_model']!='atlas-7': print('judge',t)
print(len(mism))
for m in mism: print(m)
# other anomalies
for t in T:
    if len(re.findall(r'\d+',t['judge_output'].split('FINAL SCORE')[0]))>1: pass
print(set(tm)-{s['rating_id'] for s in S})
